module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    wire [3:0] q;

    // Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Reset the counter to 1
        reset <= 1;
        #10;
        reset <= 0;

        // Apply stimulus and verify outputs
        for (int i = 0; i < 10; i++) begin
            #10;
            clk <= 1;
            #10;
            clk <= 0;
            #10;
            if (q !== $signed({i[3:0]}) ) begin
                errors = errors + 1;
            end
        end

        // Check if counter has reached 10
        #10;
        if (q !== $signed({10[3:0]}) ) begin
            errors = errors + 1;
        end

        // Print test result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        // Terminate simulation
        $finish;
    end
endmodule
